#[test]
fn svg_filters_none() {
    let actual = {
        let (deps, notices) = deps(vec![block("core/image", "", "", &[])]);
        let api = ThemeJsonApi::new(deps);
        let doc = api.construct(json(r##"{"version":3,"settings":{"color":{"duotone":[{"slug":"dark-grayscale","colors":["#000000","#7f7f7f"],"name":"dark-grayscale"},{"slug":"blue-red","colors":["#0000ff","#ff0000"],"name":"blue-red"},{"slug":"bad","colors":["nope","#fff"],"name":"bad"}]},"blocks":{"core/image":{"color":{"duotone":[{"slug":"img","colors":["rgb(1,2,3)","hsl(10,20%,30%)"],"name":"img"}]}}}}}"##), b"theme");
        notices.notices.borrow_mut().clear();
        let r = st(String::from_utf8(api.get_svg_filters(&doc, &json(r##"[]"##))).unwrap());
        pair(r, notices.notices.borrow().clone())
    };
    assert_php_eq(&actual, &json(r##"["",[]]"##));
}

